import sys
MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    masks = [[0] * (n + 2) for _ in range(n + 2)]
    p = 2
    for _ in range(m):
        l, r, x = data[p], data[p+1], data[p+2]
        p += 3
        masks[l][r] |= 1 << x
    for l in range(n, 0, -1):
        row, nxt = masks[l], masks[l+1]
        for r in range(1, n+1):
            row[r] |= nxt[r]
        cur = 0
        for r in range(1, n+1):
            cur |= row[r]
            row[r] = cur
    comb = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        comb[i][0] = comb[i][i] = 1
        for j in range(1, i):
            comb[i][j] = (comb[i-1][j-1] + comb[i-1][j]) % MOD
    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        dp[i][i-1] = 1
    for length in range(1, n + 1):
        choose = comb[length-1]
        for l in range(1, n-length+2):
            r = l + length - 1
            forbidden = masks[l][r]
            total = 0
            for k in range(l, r+1):
                if not (forbidden >> k) & 1:
                    total += dp[l][k-1] * dp[k+1][r] * choose[k-l]
            dp[l][r] = total % MOD
    print(dp[1][n])

