import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    a = [v - 1 for v in data[2:]]

    rev = [[] for _ in range(n)]
    indeg = [0] * n
    for v, p in enumerate(a):
        rev[p].append(v)
        indeg[p] += 1

    queue = [v for v in range(n) if indeg[v] == 0]
    order = []
    for v in queue:
        order.append(v)
        p = a[v]
        indeg[p] -= 1
        if indeg[p] == 0:
            queue.append(p)

    is_cycle = [indeg[v] > 0 for v in range(n)]
    component = [-1] * n
    component_count = 0
    for start in range(n):
        if is_cycle[start] and component[start] == -1:
            v = start
            while component[v] == -1:
                component[v] = component_count
                v = a[v]
            component_count += 1

    # sums[v] is the number of assignments of the non-cycle subtree at v
    # with v's value at most the current value.
    sums = [0] * n
    component_totals = [0] * component_count

    for _ in range(m):
        for v in order:
            ways = 1
            for child in rev[v]:
                if not is_cycle[child]:
                    ways = ways * sums[child] % MOD
            sums[v] = (sums[v] + ways) % MOD

        values = [1] * component_count
        for v in range(n):
            if is_cycle[v]:
                ways = 1
                for child in rev[v]:
                    if not is_cycle[child]:
                        ways = ways * sums[child] % MOD
                c = component[v]
                values[c] = values[c] * ways % MOD

        for c in range(component_count):
            component_totals[c] = (component_totals[c] + values[c]) % MOD

    answer = 1
    for value in component_totals:
        answer = answer * value % MOD
    print(answer)

if __name__ == "__main__":
    main()

