class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            right = max(x, y)
            left = min(x, y)
            by_right[right].append((left, i))

        # Among pairs whose larger endpoint has been reached, keep the
        # largest two smaller endpoints and the identity of the largest.
        largest = 0
        second = 0
        largest_id = -1
        gain = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for left, idx in by_right[right]:
                if left > largest:
                    second = largest
                    largest = left
