class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)

        fac = [1] * (L + 1)
        for i in range(1, L + 1):
            fac[i] = fac[i - 1] * i % MOD
        ifac = [1] * (L + 1)
        ifac[L] = pow(fac[L], MOD - 2, MOD)
        for i in range(L, 0, -1):
            ifac[i - 1] = ifac[i] * i % MOD

        def choose(n, r):
            if r < 0 or r > n:
                return 0
            return fac[n] * ifac[r] % MOD * ifac[n - r] % MOD

        # If x has m set bits, its first operation gives m.  Thus m
        # must reach 1 in at most k-1 further operations.
        good = [False] * (L + 1)
        for m in range(1, L + 1):
            v = m
            operations = 0
            while v != 1:
                v = v.bit_count()
                operations += 1
            good[m] = operations <= k - 1

        # Count strings strictly smaller than s, grouped by their number
        # of set bits.  At each 1 in s, place 0 and choose the suffix.
        answer = 0
        used = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = L - i - 1
                for total in range(1, L + 1):
                    if good[total]:
                        answer = (answer + choose(remaining, total - used)) % MOD
                used += 1
        return answer

