import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    mat = [0] * n
    pos = 2
    for _ in range(m):
        u, v = data[pos] - 1, data[pos + 1] - 1
        pos += 2
        mat[u] |= 1 << v
        mat[v] |= 1 << u

    rank = 0
    pivots = []
    for col in range(n):
        selected = -1
        for r in range(rank, n):
            if (mat[r] >> col) & 1:
                selected = r
                break
        if selected < 0:
            continue
        mat[rank], mat[selected] = mat[selected], mat[rank]
        for r in range(rank + 1, n):
            if (mat[r] >> col) & 1:
                mat[r] ^= mat[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    basis = []
    for f in free:
        vec = 1 << f
        for r in range(rank - 1, -1, -1):
            if ((mat[r] & vec).bit_count() & 1):
                vec |= 1 << pivots[r]
        basis.append(vec)

    answer = [0] * n
    for bit, vec in enumerate(basis):
        for vertex in range(n):
            if (vec >> vertex) & 1:
                answer[vertex] |= 1 << bit

    if any(x == 0 for x in answer):
        print("No")
    else:
        print("Yes")
        print(*answer)

