from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        odd = (n + 1) // 2
        even = n // 2
        used = [False] * (n + 1)
        answer = []
        last_parity = -1

        def completions(o: int, e: int, first_parity: int) -> int:
            if o + e == 0:
                return 1
            if o == e:
                possible = True
            elif o == e + 1:
                possible = (first_parity == 1)
            elif e == o + 1:
                possible = (first_parity == 0)
            else:
                possible = False
            return fact[o] * fact[e] if possible else 0

        for _ in range(n):
            chosen = False
            for x in range(1, n + 1):
                parity = x & 1
                if used[x] or (last_parity != -1 and parity == last_parity):
                    continue
                no = odd - parity
                ne = even - (1 - parity)
                count = completions(no, ne, 1 - parity)
                if k > count:
                    k -= count
                    continue
                used[x] = True
                answer.append(x)
                odd, even = no, ne
                last_parity = parity
                chosen = True
                break
            if not chosen:
                return []
        return answer

