class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2

        # Powers are indexed from the rightmost digit.
        power = [1] * n
        for i in range(1, n):
            power[i] = power[i - 1] * 10 % k

        # weight[i] is the contribution of the i-th digit of the
        # left half (and its mirrored digit) modulo k.
        weight = []
        for i in range(half):
            j = n - 1 - i
            if i == j:
                weight.append(power[i])
            else:
                weight.append((power[i] + power[j]) % k)

        # suffix[i] is a bitset of residues obtainable by positions i..end.
        suffix = [0] * (half + 1)
        suffix[half] = 1  # residue zero
        for i in range(half - 1, -1, -1):
            possible = 0
            for digit in range(10):
                shift = weight[i] * digit % k
                for residue in range(k):
                    if suffix[i + 1] & (1 << residue):
                        possible |= 1 << ((shift + residue) % k)
            suffix[i] = possible

        result = []
        remainder = 0
        for i in range(half):
            minimum = 1 if i == 0 else 0
            for digit in range(9, minimum - 1, -1):
                needed = (-remainder - weight[i] * digit) % k
                if suffix[i + 1] & (1 << needed):
                    result.append(str(digit))
                    remainder = (remainder + weight[i] * digit) % k
                    break

        left = ''.join(result)
        return left + left[:n // 2][::-1]

