from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nxt = [n] * n
        stack = []
        for i, x in enumerate(nums):
            while stack and nums[stack[-1]] < x:
                nxt[stack.pop()] = i
            stack.append(i)

        pref = [0] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = pref[i] + x

        levels = n.bit_length()
        up = [nxt]
        edge_cost = [
            nums[i] * (nxt[i] - i) - (pref[nxt[i]] - pref[i])
            for i in range(n)
        ]
        costs = [edge_cost]

        for _ in range(1, levels):
            old_up = up[-1]
            old_cost = costs[-1]
            new_up = [n] * n
            new_cost = [0] * n
            for i in range(n):
                middle = old_up[i]
                if middle < n:
                    new_up[i] = old_up[middle]
                    new_cost[i] = old_cost[i] + old_cost[middle]
                else:
                    new_cost[i] = old_cost[i]
            up.append(new_up)
            costs.append(new_cost)

        def interval_cost(left: int, right: int) -> int:
            node = left
            total = 0
            for j in range(levels - 1, -1, -1):
                dest = up[j][node]
                if dest <= right:
                    total += costs[j][node]
                    node = dest
            total += nums[node] * (right + 1 - node) - (pref[right + 1] - pref[node])
            return total

        answer = 0
        for left in range(n):
            lo, hi = left, n
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if interval_cost(left, mid - 1) <= k:
                    lo = mid
                else:
                    hi = mid - 1
            answer += lo - left
        return answer

