def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = [tuple(data[i:i + 2]) for i in range(2, 2 + 2 * n, 2)]

    # Sort in the order in which selected functions are applied:
    # functions with larger B/(A-1) come earlier.
    def compare(x, y):
        a, b = x
        c, d = y
        da, dc = a - 1, c - 1
        if da == 0 or dc == 0:
            if da == dc:
                return 0
            return -1 if da == 0 else 1
        cross = b * dc - d * da
        if cross > 0:
            return -1
        if cross < 0:
            return 1
        return 0

    funcs.sort(key=cmp_to_key(compare))

    dp = [-1] * (k + 1)
    dp[0] = 1
    for a, b in funcs:
        for count in range(k, 0, -1):
            if dp[count - 1] != -1:
                dp[count] = max(dp[count], a * dp[count - 1] + b)

    print(dp[k])


