from array import array

class Solution:
    def maximumSubarrayXor(self, nums, queries):
        n = len(nums)
        # mx[i*n+j] stores the largest score of a subarray contained in [i, j].
        mx = array('I', [0]) * (n * n)
        score = list(nums)

        for j in range(n):
            score[j] = nums[j]
            for i in range(j, -1, -1):
                if i < j:
                    score[i] ^= score[i + 1]
                best = score[i]
                if i < j:
                    other = mx[(i + 1) * n + j]
                    if other > best:
                        best = other
                    other = mx[i * n + j - 1]
                    if other > best:
                        best = other
                mx[i * n + j] = best

        return [mx[l * n + r] for l, r in queries]

