class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - 97] += 1

        n = len(s)
        mx = max(cnt)
        # Keeping just one (most frequent) character is always possible.
        answer = n - mx
        inf = 10**18

        # k is the positive frequency of every character retained in the
        # resulting string.  It never needs to exceed the original maximum.
        for k in range(1, mx + 1):
            # dp[carry] is the least cost after the processed letters.
            # carry is the number of occurrences moved to the next letter.
            dp = {0: 0}
            for amount in cnt:
                nxt = {}
                for carry, cost in dp.items():
                    total = amount + carry

                    # The current letter is absent from the result.
                    new_cost = cost + total
                    old = nxt.get(total, inf)
                    if new_cost < old:
                        nxt[total] = new_cost

                    # The current letter occurs k times in the result.
                    if total >= k:
                        new_carry = total - k
                        new_cost = cost + total - k
                    else:
                        new_carry = 0
                        new_cost = cost + k - total
                    old = nxt.get(new_carry, inf)
                    if new_cost < old:
                        nxt[new_carry] = new_cost
                dp = nxt

            # Any occurrences carried beyond z must be deleted.
            value = min(cost + carry for carry, cost in dp.items())
            if value < answer:
                answer = value

        return answer

