import sys
from functools import lru_cache

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M, L = data[:3]
    values = data[3:]
    K = N + M + L
    all_mask = (1 << K) - 1
    lower = [[j for j in range(K) if values[j] < values[i]] for i in range(K)]

    sys.setrecursionlimit(10000)

    @lru_cache(None)
    def winning(takahashi, aoki, turn):
        own = takahashi if turn == 0 else aoki
        if own == 0:
            return False

        x = own
        while x:
            bit = x & -x
            i = bit.bit_length() - 1
            x -= bit

            nt, na = takahashi, aoki
            if turn == 0:
                nt ^= bit
            else:
                na ^= bit

            # Play the card and take nothing.
            if not winning(nt, na, turn ^ 1):
                return True

            table = all_mask ^ (nt | na)
            for j in lower[i]:
                take_bit = 1 << j
                if table & take_bit:
                    if turn == 0:
                        child = winning(nt | take_bit, na, turn ^ 1)
                    else:
                        child = winning(nt, na | take_bit, turn ^ 1)
                    if not child:
                        return True
        return False

    initial_takahashi = (1 << N) - 1
    initial_aoki = ((1 << M) - 1) << N
    if winning(initial_takahashi, initial_aoki, 0):
        print("Takahashi")
    else:
        print("Aoki")

if __name__ == "__main__":
    main()

