import sys
MOD = 998244353

class DSU:
    __slots__ = ('p', 'size', 'xr')
    def __init__(self, n):
        self.p = list(range(n))
        self.size = [1] * n
        self.xr = [0] * n

    def find(self, a):
        if self.p[a] != a:
            old = self.p[a]
            self.p[a] = self.find(old)
            self.xr[a] ^= self.xr[old]
        return self.p[a]

    def union(self, a, b, val):
        ra = self.find(a)
        xa = self.xr[a]
        rb = self.find(b)
        xb = self.xr[b]
        if ra == rb:
            return (xa ^ xb) == val
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
            xa, xb = xb, xa
        self.p[rb] = ra
        # value[ a ] xor value[ b ] must equal val
        self.xr[rb] = xa ^ xb ^ val
        self.size[ra] += self.size[rb]
        return True

def solve(H, W, rows):
    # q is one for A and zero for B.
    # Every row and column must contain an even number of A tiles.
    for s in rows:
        if s.count('A') & 1:
            return 0
    for j in range(W):
        parity = 0
        for s in rows:
            parity ^= (s[j] == 'A')
        if parity:
            return 0

    dsu = DSU(H + W)
    col_prefix = [0] * W  # A-parity strictly above the current row
    for i, s in enumerate(rows):
        row_prefix = 0       # A-parity strictly left of current cell
        for j, ch in enumerate(s):
            q = (ch == 'A')
            if not q:         # B: the two horizontal and vertical values differ
                required = 1 ^ row_prefix ^ col_prefix[j]
                if not dsu.union(i, H + j, required):
                    return 0
            row_prefix ^= q
            col_prefix[j] ^= q

    roots = set()
    for v in range(H + W):
        roots.add(dsu.find(v))
    return pow(2, len(roots), MOD)

def main():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    pos = 1
    ans = []
    for _ in range(t):
        h = int(data[pos]); w = int(data[pos + 1]); pos += 2
        rows = [data[pos + i].decode() for i in range(h)]
        pos += h
        ans.append(str(solve(h, w, rows)))
    sys.stdout.write('\n'.join(ans))

if __name__ == '__main__':
    main()

