class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')

        def occurrences(word):
            m = len(word)
            if m == 0:
                return [], None
            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j and word[i] != word[j]:
                    j = pi[j - 1]
                if word[i] == word[j]:
                    j += 1
                pi[i] = j

            hit = bytearray(n + 1)
            j = 0
            for i, ch in enumerate(s):
                while j and ch != word[j]:
                    j = pi[j - 1]
                if ch == word[j]:
                    j += 1
                if j == m:
                    hit[i - m + 1] = 1
                    j = pi[j - 1]
            return [i for i in range(n - m + 1) if hit[i]], hit

        def next_occurrence(word):
            if not word:
                return None
            _, hit = occurrences(word)
            nxt = [n + 1] * (n + 2)
            value = n + 1
            for i in range(n, -1, -1):
                if hit[i]:
                    value = i
                nxt[i] = value
            return nxt

        nb = next_occurrence(b)
        nc = next_occurrence(c)
        la, lb, lc = len(a), len(b), len(c)
        if a:
            starts, _ = occurrences(a)
        else:
            starts = range(n + 1)

        best = n + 1
        for start in starts:
            pos = start + la
            if b:
                if pos > n:
                    continue
                mid = nb[pos]
            else:
                mid = pos
            if mid > n:
                continue

            pos = mid + lb
            if c:
                if pos > n:
                    continue
                end = nc[pos]
            else:
                end = pos
            if end <= n:
                best = min(best, end + lc - start)

        return -1 if best == n + 1 else best

