import sys

MOD = 998244353
ROOT = 3

def ntt(a, inverse):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(ROOT, (MOD - 1) // length, MOD)
        if inverse:
            wlen = pow(wlen, MOD - 2, MOD)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            for k in range(start, start + half):
                u = a[k]
                v = a[k + half] * w % MOD
                x = u + v
                if x >= MOD:
                    x -= MOD
                y = u - v
                if y < 0:
                    y += MOD
                a[k] = x
                a[k + half] = y
                w = w * wlen % MOD
        length <<= 1

    if inverse:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:]

    # This is faster than a transform for the sparse small cases.
    if n <= 4000:
        present = set(values)
        answer = 0
        for i in range(n):
            for j in range(i + 1, n):
                sm = values[i] + values[j]
                if sm % 2 == 0 and sm // 2 in present:
                    answer += 1
        print(answer)
        return

    maximum = max(values)
    size = 1
    while size <= 2 * maximum:
        size <<= 1
    a = [0] * size
    for x in values:
        a[x] = 1

    ntt(a, False)
    for i in range(size):
        a[i] = a[i] * a[i] % MOD
    ntt(a, True)

    # The convolution counts each nontrivial AP in both endpoint orders;
    # subtract the (x,x) pairs before dividing by two.
    total = sum(a[2 * x] for x in values)
    print((total - n) // 2)

