from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        inf = 10**30
        min_prefix = [inf] * k
        min_prefix[0] = 0
        prefix = 0
        answer = -inf

        for index, value in enumerate(nums, 1):
            prefix += value
            residue = index % k
            if min_prefix[residue] != inf:
                answer = max(answer, prefix - min_prefix[residue])
            if prefix < min_prefix[residue]:
                min_prefix[residue] = prefix

        return answer

