    for p in range(2, math.isqrt(limit) + 1):
        if is_prime[p]:
            start = p * p
            is_prime[start:limit + 1:p] = b'\x00' * (((limit - start) // p) + 1)

    primes = [i for i in range(2, limit + 1) if is_prime[i]]

    # Numbers of the form (p*q)^2, with distinct primes p and q.
    pairs = 0
    right = len(primes) - 1
    for left, p in enumerate(primes):
        while right > left and p * primes[right] > limit:
            right -= 1
        if right <= left:
            break
        pairs += right - left

    # Numbers of the form p^8.
    root = 1
    while (root + 1) ** 8 <= n:
        root += 1
    while root ** 8 > n:
        root -= 1
    powers = sum(p <= root for p in primes)

    print(pairs + powers)


