from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 1:
            return 0

        size = 1
        while size < n:
            size <<= 1
        hull = [None] * (2 * size)

        def add(line):
            node, left, right = 1, 0, size - 1
            while True:
                old = hull[node]
                if old is None:
                    hull[node] = line
                    return
                mid = (left + right) // 2
                if (line[0] * mid + line[1] >
                        old[0] * mid + old[1]):
                    hull[node], line = line, old
                if left == right:
                    return
                if (line[0] * left + line[1] >
                        hull[node][0] * left + hull[node][1]):
                    node = node * 2
                    right = mid
                else:
                    node = node * 2 + 1
                    left = mid + 1

        def query(x):
            node, left, right = 1, 0, size - 1
            best = -10**30
            while True:
                line = hull[node]
                if line is not None:
                    best = max(best, line[0] * x + line[1])
                if left == right:
                    return best
                mid = (left + right) // 2
                if x <= mid:
                    node = node * 2
                    right = mid
                else:
                    node = node * 2 + 1
                    left = mid + 1

        add((nums[0], 0))
        answer = 0
        for j in range(1, n):
            answer = query(j)
            add((nums[j], answer - j * nums[j]))
        return answer

