import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        LIMIT = 10000
        is_prime = [True] * LIMIT
        is_prime[0] = is_prime[1] = False
        for p in range(2, 100):
            if is_prime[p]:
                for v in range(p * p, LIMIT, p):
                    is_prime[v] = False

        if is_prime[n] or is_prime[m]:
            return -1

        places = [10 ** i for i in range(len(str(n)))]
        inf = 10 ** 30
        dist = [inf] * LIMIT
        dist[n] = n
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            for place in places:
                digit = (value // place) % 10
                if digit > 0:
                    nxt = value - place
                    if not is_prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (dist[nxt], nxt))
                if digit < 9:
                    nxt = value + place
                    if not is_prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (dist[nxt], nxt))

        return -1

