from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # Z-array of the whole array: z[i] is the LCP of nums and nums[i:]
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        ans = 0
        # First condition: nums[0:i] is a prefix of nums[i:j].
        for i in range(1, n - 1):
            if z[i] >= i:
                ans += n - max(2 * i, i + 1)

        # For a fixed length k of nums[i:j], compute LCP(nums[i:], nums[i+k:])
        # backwards.  Only k <= the length of the third part is eligible.
        for k in range(1, (n - 1) // 2 + 1):
            common = 0
            for i in range(n - k - 1, 0, -1):
                if nums[i] == nums[i + k]:
                    common = min(k, common + 1)
                else:
                    common = 0
                if i <= n - 2 * k and common == k:
                    # Remove splits already counted by the first condition.
                    if not (z[i] >= i and k >= i):
                        ans += 1
        return ans

