from typing import List

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        point_set = {tuple(p) for p in points}
        xs = sorted({x for x, y in points})
        ys = sorted({y for x, y in points})
        answer = -1

        for ix in range(len(xs)):
            for jx in range(ix + 1, len(xs)):
                x1, x2 = xs[ix], xs[jx]
                for iy in range(len(ys)):
                    for jy in range(iy + 1, len(ys)):
                        y1, y2 = ys[iy], ys[jy]
                        corners = {
                            (x1, y1), (x1, y2),
                            (x2, y1), (x2, y2)
                        }
                        if not corners.issubset(point_set):
                            continue

                        valid = True
                        for x, y in points:
                            if (x1 <= x <= x2 and y1 <= y <= y2
                                    and (x, y) not in corners):
                                valid = False
                                break
                        if valid:
                            answer = max(answer, (x2 - x1) * (y2 - y1))

        return answer

